/**
 * Data access layer for internal links generated by
 * scripts/generate-internal-links.mjs.
 *
 * Imports a JSON file from @/data/ and exposes typed accessor functions.
 */

export interface InternalLink {
  targetType: 'ratgeber' | 'static';
  targetSlug: string;
  targetTitle: string;
  /** Path relative to /{lang}/, e.g. "ratgeber/some-article" or a static page slug */
  targetPath: string;
  matchedKeywords: string[];
  relevanceScore: number;
}

interface InternalLinksData {
  generatedAt: string;
  version: number;
  pageCount: number;
  linkCount: number;
  links: Record<string, InternalLink[]>;
}

let data: InternalLinksData | null = null;

// Important: Vite will still try to resolve a dynamic import with a static string
// at build time, even inside try/catch. `import.meta.glob()` avoids hard-failing
// when the file doesn't exist yet.
const modules = import.meta.glob<{
  default: InternalLinksData;
}>('../data/current/internalLinks.json', { eager: true });

data = Object.values(modules)[0]?.default ?? null;

/**
 * Get related internal links for a page.
 *
 * @param pageType - 'ratgeber' or 'static'
 * @param slug - The page slug (e.g. "anonyme-bestattung-ablauf-kosten")
 * @param siteId - Optional site ID for static pages (e.g. "eisdiele-linden")
 */
export function getRelatedLinks(
  pageType: 'ratgeber' | 'static',
  slug: string,
  siteId?: string,
): InternalLink[] {
  if (!data?.links) return [];

  // Build the page ID matching the script's convention
  let pageId: string;
  if (pageType === 'static' && siteId) {
    pageId = `static:${siteId}:${slug}`;
  } else {
    pageId = `${pageType}:${slug}`;
  }

  return data.links[pageId] ?? [];
}
